(5105830, 744179, 98141, '<td valign="top">Great lighting, great depth, I enjoy this a lot.</td>', 'Great lighting, great depth, I enjoy this a lot.', '2008-12-04 13:04:37.000000', NULL, 1),
(5105833, 743794, 98141, '<td valign="top">Great composition, I like the b&amp;w for it, very nice pic.</td>', 'Great composition, I like the b&w for it, very nice pic.', '2008-12-04 13:04:57.000000', NULL, 1),
