(5105835, 744403, 98141, '<td valign="top">Cool idea for a pic, great colors, I dig the composition.</td>', 'Cool idea for a pic, great colors, I dig the composition.', '2008-12-04 13:05:02.000000', NULL, 1),
(5105836, 744244, 98141, '<td valign="top">Hahaha, it looks like somebody is getting beamed up in the background, I was a little freaked out that you caught a UFO on camera for a second!</td>', 'Hahaha, it looks like somebody is getting beamed up in the background, I was a little freaked out that you caught a UFO on camera for a second!', '2008-12-04 13:05:04.000000', NULL, 1),
(5105842, 744139, 98141, '<td valign="top">What exactly am I looking at here? Whatever it is, it''s awesome.</td>', 'What exactly am I looking at here? Whatever it is, it''s awesome.', '2008-12-04 13:05:36.000000', NULL, 1),
(5105844, 744168, 98141, '<td valign="top">This is exactly what my county looks like right now, it''s like looking out my window. Good job showing the low visibility, I think that''s hard to do while maintaining a good pic, sometimes it just looks oof. You did a good job.</td>', 'This is exactly what my county looks like right now, it''s like looking out my window. Good job showing the low visibility, I think that''s hard to do while maintaining a good pic, sometimes it just looks oof. You did a good job.', '2008-12-04 13:05:53.000000', NULL, 1),
(5105847, 743532, 98141, '<td valign="top">Cool idea, great colors, great capture. I like this a lot.</td>', 'Cool idea, great colors, great capture. I like this a lot.', '2008-12-04 13:06:19.000000', NULL, 1),
(5105848, 744367, 98141, '<td valign="top">I love that you did this at night, makes me feel like I''m floating in space!</td>', 'I love that you did this at night, makes me feel like I''m floating in space!', '2008-12-04 13:06:30.000000', NULL, 1),
(5105852, 742528, 98141, '<td valign="top">I love this, but I think without the wire/line on top it would be more powerful with more negative space up there.</td>', 'I love this, but I think without the wire/line on top it would be more powerful with more negative space up there.', '2008-12-04 13:07:54.000000', NULL, 1),
(5105884, 743762, 99981, '<td valign="top">Well, that''s a good perspective and you caught them on the right moment! But the size and the colors doesn''t help this photo!</td>', 'Well, that''s a good perspective and you caught them on the right moment! But the size and the colors doesn''t help this photo!', '2008-12-04 13:21:35.000000', NULL, 1),
