(5120644, 744161, 63633, '<td valign="top">Beautiful. Irene?</td>', 'Beautiful. Irene?', '2008-12-09 21:01:52.000000', NULL, 1),
(5120645, 744264, 87389, '<td valign="top">Great idea.  Suggest having the brush a bit sharper.  The grain adds the emotion of the shot.</td>', 'Great idea.  Suggest having the brush a bit sharper.  The grain adds the emotion of the shot.', '2008-12-09 21:02:50.000000', NULL, 1),
(5120646, 744111, 87389, '<td valign="top">Rich black and white. I really like the tones you have in the image, from strong white to thick black.</td>', 'Rich black and white. I really like the tones you have in the image, from strong white to thick black.', '2008-12-09 21:03:58.000000', NULL, 1),
(5120650, 744109, 87389, '<td valign="top">I like the image.  Suggest stepping up the contrast a bit.  A heavy black would help the shot to pop a bit more.</td>', 'I like the image.  Suggest stepping up the contrast a bit.  A heavy black would help the shot to pop a bit more.', '2008-12-09 21:05:01.000000', NULL, 1),
(5120653, 743794, 87389, '<td valign="top">Great idea, needs more contrast.</td>', 'Great idea, needs more contrast.', '2008-12-09 21:06:10.000000', NULL, 1),
(5120655, 743447, 87389, '<td valign="top">Lacks enough highlights.  There is a good idea for shot here.  Needs more depth.</td>', 'Lacks enough highlights.  There is a good idea for shot here.  Needs more depth.', '2008-12-09 21:09:30.000000', NULL, 1),
(5120657, 742528, 87389, '<td valign="top">Great shot.</td>', 'Great shot.', '2008-12-09 21:09:54.000000', NULL, 1),
(5120661, 744120, 87389, '<td valign="top">Nice pattern.</td>', 'Nice pattern.', '2008-12-09 21:11:22.000000', NULL, 1),
(5120663, 742389, 87389, '<td valign="top">Suggest better lighting for the shot.</td>', 'Suggest better lighting for the shot.', '2008-12-09 21:14:00.000000', NULL, 1),
(5120668, 743930, 87389, '<td valign="top">The image would work better with something in focus.  Use a small depth of field to get the soft focus.</td>', 'The image would work better with something in focus.  Use a small depth of field to get the soft focus.', '2008-12-09 21:15:27.000000', NULL, 1),
(5120674, 744386, 87389, '<td valign="top">Its got a slight edginess to it.  I like it</td>', 'Its got a slight edginess to it.  I like it', '2008-12-09 21:17:38.000000', NULL, 1),
(5120837, 744183, 75585, '<td valign="top">I wish the image was level - it tips lower on the right.  Great idea and set up</td>', 'I wish the image was level - it tips lower on the right.  Great idea and set up', '2008-12-09 22:37:22.000000', NULL, 1),
(5120847, 744075, 75585, '<td valign="top">Great addition with the black pencil coming at it - adds an extra bit of interest</td>', 'Great addition with the black pencil coming at it - adds an extra bit of interest', '2008-12-09 22:40:59.000000', NULL, 1),
(5120854, 743134, 75585, '<td valign="top">Nice illusion - I am going with "inside"</td>', 'Nice illusion - I am going with "inside"', '2008-12-09 22:43:41.000000', NULL, 1),
(5120863, 744401, 76430, '<td valign="top">Very nice geometric pattern.  I would have never figured it out without the title.  I like the angle, though downward angles are considered negative.  Too bad the resolution causes the jagged lines on the tight lines on top.</td>', 'Very nice geometric pattern.  I would have never figured it out without the title.  I like the angle, though downward angles are considered negative.  Too bad the resolution causes the jagged lines on the tight lines on top.', '2008-12-09 22:48:24.000000', NULL, 1),
(5120864, 744251, 61788, '<td valign="top">Over all architectural (excluding bridges) I like this best. Diagonal works well, pipe, and maybe that whole frame is filled with these lines.</td>', 'Over all architectural (excluding bridges) I like this best. Diagonal works well, pipe, and maybe that whole frame is filled with these lines.', '2008-12-09 22:48:33.000000', NULL, 1),
(5120865, 744107, 61788, '<td valign="top">This is one of the most original entries and I would love to see it rated high. However subject (sorry - main subject :) is so hard to present as a piece of art - that''s where I struggle - trying to rate it properly. Maybe I''m too picky - forgive me.</td>', 'This is one of the most original entries and I would love to see it rated high. However subject (sorry - main subject :) is so hard to present as a piece of art - that''s where I struggle - trying to rate it properly. Maybe I''m too picky - forgive me.', '2008-12-09 22:48:39.000000', NULL, 1),
(5120866, 744146, 61788, '<td valign="top">I like the idea of combining straight things of different nature. Rays unfortunately are not that "strong".</td>', 'I like the idea of combining straight things of different nature. Rays unfortunately are not that "strong".', '2008-12-09 22:49:08.000000', NULL, 1),
(5120876, 742263, 61788, '<td valign="top">It''s hard to not notice this image - very interesting from many points of view. I guess you show how straight lines can be bended and transformed. ?</td>', 'It''s hard to not notice this image - very interesting from many points of view. I guess you show how straight lines can be bended and transformed. ?', '2008-12-09 22:58:40.000000', NULL, 1),
(5120934, 744317, 100566, '<td valign="top">I think this is a very imaginative piece. I really like the way the color gradients work from purple to red across and through the translucent "walls." Great work!</td>', 'I think this is a very imaginative piece. I really like the way the color gradients work from purple to red across and through the translucent "walls." Great work!', '2008-12-09 23:31:50.000000', NULL, 1),
(5120954, 744317, 23098, '<td valign="top">Bright and bold colors, lighting and straight lines, make an excellent abstract.</td>', 'Bright and bold colors, lighting and straight lines, make an excellent abstract.', '2008-12-09 23:40:55.000000', NULL, 1),
(5120958, 744220, 23098, '<td valign="top">What a cool high key shot.  Neat idea. Should be a winner.</td>', 'What a cool high key shot.  Neat idea. Should be a winner.', '2008-12-09 23:42:54.000000', NULL, 1),
(5120964, 744162, 23098, '<td valign="top">One of my favorites of the buildings in the challenge.</td>', 'One of my favorites of the buildings in the challenge.', '2008-12-09 23:43:58.000000', NULL, 1),
(5120979, 744146, 23098, '<td valign="top">Nice depth.  Like the shot a lot. Maybe a slight crop of the top clouds would keep attention on those great lines. 8</td>', 'Nice depth.  Like the shot a lot. Maybe a slight crop of the top clouds would keep attention on those great lines. 8', '2008-12-09 23:49:35.000000', NULL, 1),
(5120981, 744294, 23098, '<td valign="top">Bright with great colors. Nice straight lines. Works for me.</td>', 'Bright with great colors. Nice straight lines. Works for me.', '2008-12-09 23:50:08.000000', NULL, 1),
(5120997, 744303, 23098, '<td valign="top">Moody shot and nice light.</td>', 'Moody shot and nice light.', '2008-12-09 23:54:10.000000', NULL, 1),
